<span class="line"><span style="color:#61AFEF;">kubectl</span><span style="color:#98C379;"> rollout</span><span style="color:#98C379;"> undo</span><span style="color:#98C379;"> deployment/myapp</span><span style="color:#D19A66;"> --to-revision=2</span><span style="color:#7F848E;font-style:italic;">   # 指定版本</span></span>
